SEG = "Gliederungsvorschlag; die Abgrenzung der Abschnitte ist eine redaktionelle Entscheidung."
SEG_24 = SEG + " Die Rede Jesu ([[MAT.24.4]]–[[MAT.25.46]]) läuft über die Kapitelgrenze weiter; sie wird hier nach Gedankengängen geteilt."
UNITS = [
 # (id, Bereich, Art, Titel, Teile, Zusammenfassung, Gliederungshinweis)
 ("TU-MAT-024-001-051", "MAT.24.1-MAT.24.51", "section", "Rede über das Ende: Bedrängnis, Kommen des Menschensohns, Wachsamkeit",
  ["TU-MAT-024-001-002", "TU-MAT-024-003-014", "TU-MAT-024-015-028", "TU-MAT-024-029-031", "TU-MAT-024-032-035", "TU-MAT-024-036-044", "TU-MAT-024-045-051"],
  "Als die Jünger Jesus auf die Bauten des Tempels hinweisen, kündigt er an, kein Stein werde auf dem anderen bleiben. Auf dem Ölberg fragen sie ihn, wann das sein werde und was das Zeichen seines Kommens und der Vollendung der Weltzeit sei. Jesus warnt vor Irreführung: Kriege, Hungersnöte und Erdbeben seien erst der Anfang der Wehen; die Jünger würden ausgeliefert und gehasst, falsche Propheten würden auftreten, das Evangelium vom Reich werde allen Völkern verkündigt, und dann komme das Ende. Wenn sie den Gräuel der Verwüstung an heiliger Stätte sehen, sollen die in Judäa fliehen, denn es komme eine Bedrängnis, wie es keine gegeben hat; falschen Christussen sollen sie nicht glauben. Danach würden Sonne und Mond ihren Schein verlieren, die Sterne fallen, und man werde den Menschensohn auf den Wolken des Himmels kommen sehen; er werde seine Auserwählten sammeln. Am Feigenbaum sollen sie die Nähe erkennen; Tag und Stunde kenne niemand ausser dem Vater. Wie in den Tagen Noahs komme es unerwartet, darum sollen sie wachen und bereit sein. Das Gleichnis vom treuen und vom bösen Knecht zeigt, was beiden geschieht, wenn ihr Herr kommt.", SEG_24),
 ("TU-MAT-024-001-002", "MAT.24.1-MAT.24.2", "dialogue", "Kein Stein auf dem anderen", None,
  "Jesus verlässt den Tempel; seine Jünger treten heran, um ihm die Bauten des Tempels zu zeigen. Jesus fragt, ob sie nicht all das sehen, und kündigt an, hier werde kein Stein auf dem anderen gelassen, der nicht abgebrochen wird.", None),
 ("TU-MAT-024-003-014", "MAT.24.3-MAT.24.14", "discourse", "Der Anfang der Wehen", None,
  "Auf dem Ölberg fragen die Jünger Jesus für sich allein, wann das sein werde und was das Zeichen seines Kommens und der Vollendung der Weltzeit sei. Jesus warnt sie, sich nicht irreführen zu lassen: Viele würden unter seinem Namen kommen und sagen, sie seien der Christus. Kriege, Hungersnöte und Erdbeben müssten geschehen, seien aber erst der Anfang der Wehen. Man werde die Jünger der Bedrängnis ausliefern und töten, und alle Völker würden sie hassen; viele würden zu Fall kommen, falsche Propheten auftreten und die Liebe der vielen erkalten. Wer bis ans Ende standhält, werde gerettet. Das Evangelium vom Reich werde in der ganzen Welt allen Völkern zum Zeugnis verkündigt, und dann komme das Ende.", None),
 ("TU-MAT-024-015-028", "MAT.24.15-MAT.24.28", "discourse", "Die grosse Bedrängnis", None,
  "Jesus sagt: Wenn die Jünger den Gräuel der Verwüstung, von dem der Prophet Daniel gesprochen hat, an heiliger Stätte stehen sehen, sollen die in Judäa in die Berge fliehen, ohne noch etwas aus dem Haus oder vom Feld zu holen; wehe den Schwangeren und Stillenden, und sie sollen beten, dass die Flucht nicht im Winter oder an einem Sabbat geschieht. Dann werde eine grosse Bedrängnis sein, wie es keine gegeben hat und keine geben wird; um der Auserwählten willen würden jene Tage verkürzt. Wenn jemand sagt, der Christus sei hier oder dort, in der Wüste oder in den Kammern, sollen sie es nicht glauben: Falsche Christusse und falsche Propheten würden grosse Zeichen und Wunder tun, sodass sie, wenn möglich, sogar die Auserwählten irreführen. Das Kommen des Menschensohns werde sein wie der Blitz, der von Osten bis Westen leuchtet; wo das Aas ist, da versammeln sich die Geier.", None),
 ("TU-MAT-024-029-031", "MAT.24.29-MAT.24.31", "discourse", "Das Kommen des Menschensohns", None,
  "Jesus kündigt an: Sogleich nach der Bedrängnis jener Tage werde die Sonne verfinstert, der Mond gebe seinen Schein nicht, die Sterne fielen vom Himmel, und die Mächte der Himmel würden erschüttert. Dann erscheine das Zeichen des Menschensohns am Himmel, alle Stämme der Erde würden wehklagen und den Menschensohn auf den Wolken des Himmels kommen sehen, mit Macht und grosser Herrlichkeit. Er werde seine Engel mit lauter Posaune aussenden, und sie würden seine Auserwählten aus den vier Winden sammeln.", None),
 ("TU-MAT-024-032-035", "MAT.24.32-MAT.24.35", "parable", "Das Gleichnis vom Feigenbaum", None,
  "Jesus sagt, die Jünger sollen am Feigenbaum lernen: Wenn sein Zweig zart wird und Blätter treibt, ist der Sommer nahe; ebenso sollen sie, wenn sie all das sehen, erkennen, dass er (oder: es) nahe vor den Türen ist. Dieses Geschlecht werde nicht vergehen, bis all das geschieht; Himmel und Erde würden vergehen, seine Worte aber nicht.", None),
 ("TU-MAT-024-036-044", "MAT.24.36-MAT.24.44", "discourse", "Niemand kennt Tag und Stunde", None,
  "Jesus sagt, jenen Tag und jene Stunde kenne niemand, auch nicht die Engel und auch nicht der Sohn, sondern allein der Vater. Wie die Menschen in den Tagen vor der Flut assen, tranken und heirateten und nichts merkten, bis die Flut kam und alle wegraffte, so werde es beim Kommen des Menschensohns sein: Von zweien auf dem Feld oder an der Mühle werde der eine mitgenommen, der andere zurückgelassen. Darum sollen die Jünger wachen, denn sie wissen nicht, an welchem Tag ihr Herr kommt. Hätte ein Hausherr gewusst, wann der Dieb kommt, hätte er gewacht; so sollen auch sie bereit sein, denn der Menschensohn kommt zu einer Stunde, in der sie es nicht meinen.", None),
 ("TU-MAT-024-045-051", "MAT.24.45-MAT.24.51", "parable", "Der treue und der böse Knecht", None,
  "Jesus fragt, wer der treue und kluge Knecht sei, den der Herr über seine Dienerschaft gesetzt hat, damit er ihnen zur rechten Zeit das Essen gibt. Selig sei der Knecht, den sein Herr bei seiner Rückkehr bei diesem Tun antrifft; er werde ihn über seinen ganzen Besitz setzen. Wenn aber der böse Knecht denkt, sein Herr lasse auf sich warten, seine Mitknechte schlägt und mit den Betrunkenen isst und trinkt, werde der Herr an einem unerwarteten Tag kommen, ihn in Stücke hauen und ihm seinen Anteil bei den Heuchlern zuweisen, wo das Weinen und das Zähneknirschen sein wird.", None),
 ("TU-MAT-025-001-046", "MAT.25.1-MAT.25.46", "section", "Gleichnisse vom Warten und das Gericht über die Völker",
  ["TU-MAT-025-001-013", "TU-MAT-025-014-030", "TU-MAT-025-031-046"],
  "Jesus setzt seine Rede fort. Das Reich der Himmel werde zehn Jungfrauen gleichen, die dem Bräutigam mit ihren Lampen entgegengehen: Nur die fünf klugen haben Öl mitgenommen; als der Bräutigam um Mitternacht kommt, gehen sie mit ihm zur Hochzeit hinein, während die törichten Öl kaufen gehen und danach zur Antwort bekommen: «Ich kenne euch nicht.» Darum sollen die Jünger wachen. Ein Mensch, der verreist, vertraut seinen Knechten fünf, zwei und ein Talent an; die ersten beiden gewinnen ebenso viel dazu und werden gelobt, der dritte vergräbt sein Talent aus Furcht, und der Herr befiehlt, es ihm zu nehmen und ihn in die äussere Finsternis hinauszuwerfen. Zum Schluss kündigt Jesus an: Wenn der Menschensohn in seiner Herrlichkeit kommt, werden alle Völker vor ihm versammelt, und er wird sie scheiden wie ein Hirt die Schafe von den Böcken. Als König wird er denen zu seiner Rechten sagen, was sie einem seiner geringsten Brüder getan haben, als sie Hungrigen zu essen gaben, Fremde aufnahmen und Kranke und Gefangene besuchten, das hätten sie ihm getan; denen zur Linken wird er sagen, sie hätten es ihm nicht getan. Diese gehen in ewige Strafe, die Gerechten in ewiges Leben.", SEG),
 ("TU-MAT-025-001-013", "MAT.25.1-MAT.25.13", "parable", "Die zehn Jungfrauen", None,
  "Jesus sagt, das Reich der Himmel werde zehn Jungfrauen gleichen, die ihre Lampen nehmen und dem Bräutigam entgegengehen. Fünf sind töricht und nehmen kein Öl mit, fünf sind klug und nehmen Öl in Gefässen mit. Als der Bräutigam auf sich warten lässt, werden alle schläfrig und schlafen. Um Mitternacht erhebt sich ein Geschrei: «Siehe, der Bräutigam!» Die törichten bitten die klugen um Öl, weil ihre Lampen ausgehen; diese antworten, es könnte nicht für beide reichen, und schicken sie zu den Händlern. Während sie kaufen gehen, kommt der Bräutigam; die bereit waren, gehen mit ihm zur Hochzeit hinein, und die Tür wird verschlossen. Als die übrigen Jungfrauen später rufen «Herr, Herr, mach uns auf!», antwortet er: «Ich kenne euch nicht.» Darum sollen die Hörer wachen, denn sie kennen weder den Tag noch die Stunde.", None),
 ("TU-MAT-025-014-030", "MAT.25.14-MAT.25.30", "parable", "Die anvertrauten Talente", None,
  "Jesus erzählt von einem Menschen, der verreisen will und seinen Knechten seinen Besitz übergibt: dem einen fünf Talente, dem anderen zwei, dem dritten eines, jedem nach seiner Fähigkeit. Der mit den fünf und der mit den zwei Talenten arbeiten damit und gewinnen je ebenso viel dazu; der dritte gräbt ein Loch in die Erde und verbirgt das Geld seines Herrn. Nach langer Zeit rechnet der Herr mit ihnen ab: Die beiden ersten nennt er gute und treue Knechte, verspricht, sie über vieles zu setzen, und heisst sie in die Freude ihres Herrn eintreten. Der dritte sagt, er habe gewusst, dass sein Herr ein harter Mensch sei, der erntet, wo er nicht gesät hat; aus Furcht habe er das Talent vergraben, hier habe er das Seine. Der Herr nennt ihn einen bösen und faulen Knecht: Er hätte das Geld den Geldwechslern bringen sollen, dann hätte er es mit Zinsen zurückerhalten. Er befiehlt, ihm das Talent zu nehmen und dem mit den zehn Talenten zu geben, denn wer hat, dem wird gegeben, und wer nicht hat, dem wird auch das genommen, was er hat; den nutzlosen Knecht sollen sie in die äussere Finsternis hinauswerfen.", None),
 ("TU-MAT-025-031-046", "MAT.25.31-MAT.25.46", "discourse", "Das Gericht über die Völker", None,
  "Jesus kündigt an: Wenn der Menschensohn in seiner Herrlichkeit mit allen Engeln kommt, wird er sich auf den Thron seiner Herrlichkeit setzen; alle Völker werden vor ihm versammelt, und er wird sie voneinander scheiden wie ein Hirt die Schafe von den Böcken. Als König wird er zu denen zu seiner Rechten sagen, sie sollen das Reich erben, das ihnen seit der Grundlegung der Welt bereitet ist, denn er sei hungrig, durstig, fremd, nackt, krank und im Gefängnis gewesen, und sie hätten ihm zu essen und zu trinken gegeben, ihn aufgenommen, bekleidet und besucht. Auf ihre Frage, wann sie ihn so gesehen hätten, wird er antworten: Was sie einem dieser seiner geringsten Brüder getan haben, das haben sie ihm getan. Zu denen zur Linken wird er sagen, sie sollen als Verfluchte in das ewige Feuer gehen, das für den Teufel und seine Engel bereitet ist, denn sie hätten ihm das alles nicht getan; auf ihre Frage wird er antworten, was sie einem dieser Geringsten nicht getan haben, hätten sie auch ihm nicht getan. Diese werden in ewige Strafe gehen, die Gerechten in ewiges Leben.", None),
]
UNITS_GSW = {
 "TU-MAT-024-001-051": ("Red über s Änd: Bedrängnis, Aachunft vom Mänschesohn, Wachsamkeit", "Wo d Jünger de Jesus uf d Bauwärch vom Tämpel hiiwised, seit er, es bliib kei Stei uf em andere. Uf em Ölberg fröged si en, wänn das sig und was s Zeiche vo sinere Aachunft und vo de Vollendig vo de Wältziit sig. De Jesus warnt devor, sich in d Irri füere z laa: Chrieg, Hungersnöt und Ärdbebe seigid erscht de Aafang vo de Wehe; d Jünger wärdid usgliferet und ghasst, falschi Prophete wärdid uftrete, s Evangelium vom Riich wärdi allne Völker verchündet, und dänn chömm s Änd. Wänn si de Gröiel vo de Verwüeschtig am heilige Ort gsehnd, söled die z Judäa flüchte, dänn es chömm e Bedrängnis, wie s keini gää hät; falsche Christusse söled si nöd glaube. Dänn wärdid Sunne und Mond kei Liecht meh gää, d Stärne abegheie, und mer wärdi de Mänschesohn uf de Wolche vom Himel gseh choo; er wärdi sini Uuserwäälte zämehole. Am Fiigebaum söled si merke, dass es nöch isch; Tag und Stund wüss niemer usser em Vatter. Wie i de Täg vom Noah chömm s unerwartet, drum söled si wach bliibe und parat sii. S Gliichnis vom treue und vom bööse Chnächt zeigt, was beidne passiert, wänn ire Herr chunnt."),
 "TU-MAT-024-001-002": ("Kei Stei uf em andere", "De Jesus gaat us em Tämpel; sini Jünger chömed häre, für ihm d Bauwärch vom Tämpel z zeige. De Jesus fröget, öb si nöd das alles gsehnd, und seit, da bliib kei Stei uf em andere, wo nöd abbroche wärdi."),
 "TU-MAT-024-003-014": ("De Aafang vo de Wehe", "Uf em Ölberg fröged d Jünger de Jesus für sich elei, wänn das sig und was s Zeiche vo sinere Aachunft und vo de Vollendig vo de Wältziit sig. De Jesus warnt si, sich nöd in d Irri füere z laa: Vili wärdid i sim Name choo und säge, si seigid de Christus. Chrieg, Hungersnöt und Ärdbebe müesid passiere, seigid aber erscht de Aafang vo de Wehe. Mer wärdi d Jünger de Bedrängnis uslifere und töte, und alli Völker wärdid si hasse; vili wärdid z Fall choo, falschi Prophete uftrete und d Liebi vo de vile chalt wärde. Wer bis as Änd durehebt, wärdi grettet. S Evangelium vom Riich wärdi i de ganze Wält allne Völker zum Zügnis verchündet, und dänn chömm s Änd."),
 "TU-MAT-024-015-028": ("Di gross Bedrängnis", "De Jesus seit: Wänn d Jünger de Gröiel vo de Verwüeschtig, vo däm de Prophet Daniel gredt hät, am heilige Ort gsehnd staa, söled die z Judäa i d Bärge flüchte, ohni no öppis us em Huus oder vom Fäld z hole; weh de Schwangere und dene, wo stilled, und si söled bätte, dass d Flucht nöd im Winter oder amene Sabbat passiert. Dänn chömm e grossi Bedrängnis, wie s keini gää hät und keini meh gää wird; wäge de Uuserwäälte wärdid die Täg verchürzt. Wänn öpper seit, de Christus sig da oder det, i de Wüeschti oder i de Chammere, söled si s nöd glaube: Falschi Christusse und falschi Prophete wärdid grossi Zeiche und Wunder tue, so dass si, wänn mögli, sogar d Uuserwäälte in d Irri füered. D Aachunft vom Mänschesohn sig wie de Blitz, wo vom Oschte bis in Weschte lüüchtet; wo s Aas isch, det sammled sich d Geier."),
 "TU-MAT-024-029-031": ("D Aachunft vom Mänschesohn", "De Jesus seit aa: Grad nach de Bedrängnis vo dene Täg wärdi d Sunne dunkel, de Mond gäb sis Liecht nöd, d Stärne gheiid vom Himel abe, und d Mächt vo de Himel wärdid erschütteret. Dänn erschiin s Zeiche vom Mänschesohn am Himel, alli Stämm vo de Ärde wärdid chlage und de Mänschesohn uf de Wolche vom Himel gseh choo, mit Macht und grosser Herrlichkeit. Er wärdi sini Ängel mit luuter Posuune usschicke, und si wärdid sini Uuserwäälte us de vier Wind zämehole."),
 "TU-MAT-024-032-035": ("S Gliichnis vom Fiigebaum", "De Jesus seit, d Jünger söled vom Fiigebaum lehre: Wänn sin Zweig weich wird und Bletter tribt, isch de Summer nöch; gliich söled si, wänn si das alles gsehnd, merke, dass er (oder: es) nöch vor de Türe isch. Die Generation vergang nöd, bis das alles passiert; Himel und Ärde vergöngid, sini Wort aber nöd."),
 "TU-MAT-024-036-044": ("Niemer weiss Tag und Stund", "De Jesus seit, vo dem Tag und dere Stund wüss niemer öppis, au nöd d Ängel und au nöd de Sohn, nu de Vatter elei. Wie d Lüüt i de Täg vor de Sintflut ggässe, trunke und ghürate händ und nüüt gmerkt händ, bis d Sintflut choo isch und alli mitgrisse hät, so sig s bi de Aachunft vom Mänschesohn: Vo zwei uf em Fäld oder a de Müli wärdi de eint mitgnoo, de ander zrugglaa. Drum söled d Jünger wach bliibe, dänn si wüssed nöd, a welem Tag ire Herr chunnt. Hett en Huusherr gwüsst, wänn de Dieb chunnt, hett er gwachet; so söled au si parat sii, dänn de Mänschesohn chunnt zu ere Stund, wo si s nöd meined."),
 "TU-MAT-024-045-051": ("De treu und de böös Chnächt", "De Jesus fröget, wer de treu und gschiid Chnächt sig, wo de Herr über sini Dienerschaft gsetzt hät, dass er ine zur rächte Ziit s Ässe git. Sälig sig dä Chnächt, wo sin Herr bi sinere Rückkehr bi däm Tue aatrifft; er wärdi en über sin ganze Bsitz setze. Wänn aber de böös Chnächt dänkt, sin Herr laa uf sich warte, sini Mitchnächt schlaat und mit de Bsoffne isst und trinkt, chömm de Herr amene unerwartete Tag, haui en in Stück und gäb ihm sin Aateil bi de Hüüchler, wo s Hüüle und s Zändchnirsche isch."),
 "TU-MAT-025-001-046": ("Gliichnis vom Warte und s Gricht über d Völker", "De Jesus redt wiiter. S Riich vo de Himel wärdi zäh Jumpfere gliiche, wo mit ire Lampe em Brüütigam entgäge gönd: Nu di föif gschiide händ Öl mitgnoo; wo de Brüütigam z Mitternacht chunnt, gönd si mit ihm a d Hochziit ine, wääred di tumme go Öl chaufe und nachher zur Antwort überchömed: «Ich kenn eu nöd.» Drum söled d Jünger wach bliibe. En Mänsch, wo verreist, vertrout sine Chnächt föif, zwei und eis Talänt aa; di erschte zwei gwünned gliich vil dezue und wärded globt, de dritt vergrabt sis Talänt us Angscht, und de Herr befiehlt, es ihm wägznää und en i d üsseri Fiischteri usezrüere. Zum Schluss seit de Jesus aa: Wänn de Mänschesohn i sinere Herrlichkeit chunnt, wärded alli Völker vor ihm versammlet, und er tränt si wie en Hirt d Schaf vo de Böck. Als König wird er dene uf sinere rächte Siite säge, was si eim vo sine chliinschte Brüedere gmacht heigid, wo si Hungrige z ässe gää, Fremdi ufgnoo und Chranki und Gfangni psuecht händ, das heigid si ihm gmacht; dene uf de lingge Siite wird er säge, si heigid s ihm nöd gmacht. Die gönd i ewigi Straf, di Grächte i ewigs Läbe."),
 "TU-MAT-025-001-013": ("Di zäh Jumpfere", "De Jesus seit, s Riich vo de Himel wärdi zäh Jumpfere gliiche, wo iri Lampe nämed und em Brüütigam entgäge gönd. Föif sind tumm und nämed kei Öl mit, föif sind gschiid und nämed Öl i Gfäss mit. Wo de Brüütigam uf sich warte laat, wärded alli schläfrig und schlafed. Z Mitternacht gaat es Gschrei los: «Lueg, de Brüütigam!» Di tumme bitted di gschiide um Öl, wil iri Lampe usgönd; die antworted, es chönnt nöd für alli länge, und schicked si zu de Händler. Wääred si go chaufe gönd, chunnt de Brüütigam; die, wo parat gsii sind, gönd mit ihm a d Hochziit ine, und d Tür wird zuegschlosse. Wo di andere Jumpfere spöter rüefed «Herr, Herr, mach üs uf!», antwortet er: «Ich kenn eu nöd.» Drum söled d Zuehörer wach bliibe, dänn si wüssed wäder de Tag no d Stund."),
 "TU-MAT-025-014-030": ("Di aavertroute Talänt", "De Jesus verzellt vo me Mänsch, wo wott verreise und sine Chnächt sin Bsitz übergit: em eint föif Talänt, em andere zwei, em dritte eis, jedem nach sim Chönne. Dä mit de föif und dä mit de zwei Talänt schaffed damit und gwünned je gliich vil dezue; de dritt grabt es Loch in Bode und versteckt s Gäld vo sim Herr. Nach langer Ziit rächnet de Herr mit ine ab: Di erschte zwei nännt er gueti und treui Chnächt, verspricht, si über vil z setze, und seit ine, si söled i d Fröid vo irem Herr inechoo. De dritt seit, er heig gwüsst, dass sin Herr en harte Mänsch sig, wo ärntet, wo er nöd gsäit hät; us Angscht heig er s Talänt vergrabe, da heig er s Sini. De Herr nännt en en bööse und fuule Chnächt: Er hett s Gäld de Gäldwächsler söle bringe, dänn hett er s mit Zins zrugg übercho. Er befiehlt, ihm s Talänt wägznää und däm mit de zäh Talänt z gää, dänn wer hät, däm wird gää, und wer nöd hät, däm wird au das wäggnoo, wo er hät; de unnütz Chnächt söled si i d üsseri Fiischteri userüere."),
 "TU-MAT-025-031-046": ("S Gricht über d Völker", "De Jesus seit aa: Wänn de Mänschesohn i sinere Herrlichkeit mit allne Ängel chunnt, setzt er sich uf de Thron vo sinere Herrlichkeit; alli Völker wärded vor ihm versammlet, und er tränt si vonenand wie en Hirt d Schaf vo de Böck. Als König wird er zu dene uf sinere rächte Siite säge, si söled s Riich erbe, wo ine sit de Grundlegig vo de Wält parat gmacht isch, dänn er heig Hunger und Durscht gha, sig fremd, blutt, chrank und im Gfängnis gsii, und si heigid ihm z ässe und z trinke gää, en ufgnoo, aagleit und psuecht. Uf iri Frag, wänn si en eso gseh heigid, wird er antworte: Was si eim vo dene chliinschte Brüedere vo ihm gmacht händ, das händ si ihm gmacht. Zu dene uf de lingge Siite wird er säge, si söled als Verfluechti is ewig Füür gaa, wo für de Tüüfel und sini Ängel parat gmacht isch, dänn si heigid ihm das alles nöd gmacht; uf iri Frag wird er antworte, was si eim vo dene Chliinschte nöd gmacht händ, heigid si au ihm nöd gmacht. Die gönd i ewigi Straf, di Grächte i ewigs Läbe."),
}

